-- FOXEY Arcade · 24 extra real meme questions for 60-question Survival.
-- No tech trivia, no copied or unlicensed media, and no changes to existing saves.
BEGIN;
CREATE TABLE IF NOT EXISTS arcade_private.quizoria_meme_bonus_questions (
 id text PRIMARY KEY,
 image_key text NOT NULL REFERENCES arcade_private.foxey_media_assets(asset_key),
 difficulty text NOT NULL CHECK(difficulty IN ('easy','medium','hard')),
 prompt_cs text NOT NULL,
 prompt_en text NOT NULL,
 options jsonb NOT NULL CHECK(jsonb_typeof(options)='array' AND jsonb_array_length(options)=4),
 answer_index integer NOT NULL CHECK(answer_index BETWEEN 0 AND 3),
 image_url text NOT NULL,
 source_url text NOT NULL,
 author text NOT NULL,
 license text NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE arcade_private.quizoria_meme_bonus_questions ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON arcade_private.quizoria_meme_bonus_questions FROM PUBLIC,anon,authenticated;
WITH input AS (
 SELECT * FROM jsonb_to_recordset('[{"id":"meme2-doge-easy-2","image_key":"doge","difficulty":"easy","prompt_cs":"Jaké plemeno psa proslavilo mem Doge?","prompt_en":"Which dog breed became famous through Doge?","options":[{"key":0,"cs":"Mops","en":"Pug"},{"key":1,"cs":"Corgi","en":"Corgi"},{"key":2,"cs":"Shiba Inu","en":"Shiba Inu"},{"key":3,"cs":"Husky","en":"Husky"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-doge.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Doge_meme_example.jpg","answer_index":1},{"id":"meme2-doge-medium-2","image_key":"doge","difficulty":"medium","prompt_cs":"Co v klasickém Doge memu představují barevné nápisy kolem psa?","prompt_en":"What do the colored phrases around Doge represent?","options":[{"key":0,"cs":"Reklamu na krmivo","en":"A dog food advertisement"},{"key":1,"cs":"Titulky k filmu","en":"Film subtitles"},{"key":2,"cs":"Psí povely","en":"Dog commands"},{"key":3,"cs":"Jeho komicky jednoduché myšlenky","en":"His comically simple thoughts"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-doge.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Doge_meme_example.jpg","answer_index":3},{"id":"meme2-doge-hard-2","image_key":"doge","difficulty":"hard","prompt_cs":"Který z těchto popisků by nejlépe seděl k Doge?","prompt_en":"Which of these captions best fits Doge?","options":[{"key":0,"cs":"Never gonna give you up","en":"Never gonna give you up"},{"key":1,"cs":"Such wow. Much surprise.","en":"Such wow. Much surprise."},{"key":2,"cs":"I can has cheezburger?","en":"I can has cheezburger?"},{"key":3,"cs":"It ain''t much but it''s honest work","en":"It ain''t much but it''s honest work"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-doge.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Doge_meme_example.jpg","answer_index":1},{"id":"meme2-lolcat-cheezburger-easy-2","image_key":"burger","difficulty":"easy","prompt_cs":"O co kočka v memu žádá?","prompt_en":"What does the cat ask for in this meme?","options":[{"key":0,"cs":"Zmrzlinu","en":"Ice cream"},{"key":1,"cs":"Kousek pizzy","en":"A slice of pizza"},{"key":2,"cs":"Kávu","en":"Coffee"},{"key":3,"cs":"Hamburger se sýrem","en":"A cheeseburger"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-lolcat-cheezburger.jpg","source_url":"https://commons.wikimedia.org/wiki/File:I_can_has_cheezburger.jpg","answer_index":3},{"id":"meme2-lolcat-cheezburger-medium-2","image_key":"burger","difficulty":"medium","prompt_cs":"Co je na nápisech LOLcats schválně legrační?","prompt_en":"What''s intentionally funny about LOLcat captions?","options":[{"key":0,"cs":"Nesmí obsahovat žádné slovo","en":"They contain no words"},{"key":1,"cs":"Zkomolená gramatika a pravopis","en":"Intentionally broken grammar and spelling"},{"key":2,"cs":"Vždy jsou psané latinsky","en":"They''re always in Latin"},{"key":3,"cs":"Jde o filmové titulky","en":"They''re film subtitles"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-lolcat-cheezburger.jpg","source_url":"https://commons.wikimedia.org/wiki/File:I_can_has_cheezburger.jpg","answer_index":1},{"id":"meme2-lolcat-cheezburger-hard-2","image_key":"burger","difficulty":"hard","prompt_cs":"Čím vzniká pointa memu „I Can Has Cheezburger“?","prompt_en":"What makes the ''I Can Has Cheezburger'' meme funny?","options":[{"key":0,"cs":"Kočka učí matematiku","en":"The cat teaches mathematics"},{"key":1,"cs":"Kočka vyhrává závod","en":"The cat wins a race"},{"key":2,"cs":"Kočka předpovídá počasí","en":"The cat predicts the weather"},{"key":3,"cs":"Kočka jako člověk prosí legračně pokaženou angličtinou","en":"A cat asks like a person using hilariously broken English"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-lolcat-cheezburger.jpg","source_url":"https://commons.wikimedia.org/wiki/File:I_can_has_cheezburger.jpg","answer_index":3},{"id":"meme2-crying-cat-easy-2","image_key":"crying","difficulty":"easy","prompt_cs":"Jakou emoci kočka v memu přehání?","prompt_en":"Which emotion does this cat meme exaggerate?","options":[{"key":0,"cs":"Nudu","en":"Boredom"},{"key":1,"cs":"Smutek","en":"Sadness"},{"key":2,"cs":"Vítězství","en":"Victory"},{"key":3,"cs":"Pýchu","en":"Pride"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-crying-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Cat_crying_(Lolcat).jpg","answer_index":1},{"id":"meme2-crying-cat-medium-2","image_key":"crying","difficulty":"medium","prompt_cs":"Který popisek nejlépe sedí k tomuhle obrázku?","prompt_en":"Which caption suits this picture best?","options":[{"key":0,"cs":"Když ti přijde výplata","en":"When payday arrives"},{"key":1,"cs":"Když vyhraješ závod","en":"When you win a race"},{"key":2,"cs":"Když je pátek odpoledne","en":"When it''s Friday afternoon"},{"key":3,"cs":"Když ti zbývá jediný díl seriálu","en":"When you''ve only got one episode left"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-crying-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Cat_crying_(Lolcat).jpg","answer_index":3},{"id":"meme2-crying-cat-hard-2","image_key":"crying","difficulty":"hard","prompt_cs":"Která situace by v Crying Cat působila nejvtipněji?","prompt_en":"Which situation would work best as a Crying Cat meme?","options":[{"key":0,"cs":"Když se vyspíš do růžova","en":"When you have a great night''s sleep"},{"key":1,"cs":"Když někdo sní poslední kousek tvé pizzy","en":"When someone eats the last slice of your pizza"},{"key":2,"cs":"Když zapneš světlo","en":"When you turn on a light"},{"key":3,"cs":"Když získáš dárek","en":"When you receive a gift"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-crying-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Cat_cryin