difficulty":"easy","prompt_cs":"Kdo je na známém memu „Honest Work“?","prompt_en":"Who is pictured in the famous ''Honest Work'' meme?","options":[{"key":0,"cs":"Kuchař","en":"A chef"},{"key":1,"cs":"Farmář","en":"A farmer"},{"key":2,"cs":"Pilot","en":"A pilot"},{"key":3,"cs":"Astronaut","en":"An astronaut"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-honest-work.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Ohio_farmer_David_Brandt.jpg","answer_index":1},{"id":"meme2-honest-work-medium-2","image_key":"honest","difficulty":"medium","prompt_cs":"Co by byl nejlepší popisek k tomuhle memu?","prompt_en":"Which is the best caption for this meme?","options":[{"key":0,"cs":"Vyhrál jsem olympiádu","en":"I won the Olympics"},{"key":1,"cs":"Právě vybuchla sopka","en":"A volcano just erupted"},{"key":2,"cs":"Ztratil jsem telefon","en":"I lost my phone"},{"key":3,"cs":"Umyla jsem jeden hrnek a mám hotovo","en":"I washed one mug and called it a day"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-honest-work.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Ohio_farmer_David_Brandt.jpg","answer_index":3},{"id":"meme2-honest-work-hard-2","image_key":"honest","difficulty":"hard","prompt_cs":"Jaký typ nadsázky má mem „Honest Work“?","prompt_en":"What kind of exaggeration does the ''Honest Work'' meme use?","options":[{"key":0,"cs":"Romantické vyznání","en":"A romantic confession"},{"key":1,"cs":"Skromná, sebeironická oslava maličkosti","en":"A humble, self-deprecating celebration of something tiny"},{"key":2,"cs":"Hrůzostrašnou výhrůžku","en":"A terrifying threat"},{"key":3,"cs":"Neřešitelnou záhadu","en":"An unsolvable mystery"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-honest-work.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Ohio_farmer_David_Brandt.jpg","answer_index":1},{"id":"meme2-touch-grass-easy-2","image_key":"q23m