dia/commons/meme-touch-grass.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Touch_grass.jpg","answer_index":3},{"id":"meme2-rickroll-qr-easy-2","image_key":"rickqr","difficulty":"easy","prompt_cs":"Jaká past bývá v memu „Rickroll“ ukrytá?","prompt_en":"What surprise is hidden in a Rickroll?","options":[{"key":0,"cs":"Pravidla deskové hry","en":"Board game rules"},{"key":1,"cs":"Nečekané hudební video","en":"An unexpected music video"},{"key":2,"cs":"Tajná mapa pokladu","en":"A treasure map"},{"key":3,"cs":"Recept na pizzu","en":"A pizza recipe"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-rickroll-qr.png","source_url":"https://commons.wikimedia.org/wiki/File:RickRoll_QR_Code.png","answer_index":1},{"id":"meme2-rickroll-qr-medium-2","image_key":"rickqr","difficulty":"medium","prompt_cs":"Jak obvykle Rickroll funguje?","prompt_en":"How does a Rickroll usually work?","options":[{"key":0,"cs":"Vypne ti monitor","en":"It turns off your screen"},{"key":1,"cs":"Pošle ti náhodnou SMS","en":"It sends a random text"},{"key":2,"cs":"Skryje všechny fotografie","en":"It hides your photos"},{"key":3,"cs":"Naláká tě na něco jiného a místo toho pustí známý klip","en":"It promises something else but plays the famous music video"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-rickroll-qr.png","source_url":"https://commons.wikimedia.org/wiki/File:RickRoll_QR_Code.png","answer_index":3},{"id":"meme2-rickroll-qr-hard-2","image_key":"rickqr","difficulty":"hard","prompt_cs":"Proč může fungovat i Rickroll schovaný za QR kódem?","prompt_en":"Why can a Rickroll work behind a QR code too?","options":[{"key":0,"cs":"Kód mění barvu po kliknutí","en":"The code changes color when clicked"},{"key":1,"cs":"Obsah cíle neznáš, dokud ho neotevřeš","en":"You don''t know the destination until opening it"},{"key":2,"cs":"Každý QR kód obsahuje hudbu","en":"Every QR code contains music"},{"key":3,"cs":"Každý obrázek je animovaný","en":"Every image is animated"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-rickroll-qr.png","source_url":"https://commons.wikimedia.org/wiki/File:RickRoll_QR_Code.png","answer_index":1},{"id":"meme2-sleepy-keyboard-cat-easy-2","image_key":"q23meme-keyboard-sleep","difficulty":"easy","prompt_cs":"Jakou reakci bys tímhle kočičím memem vyjádřil?","prompt_en":"What reaction would this sleepy cat meme express?","options":[{"key":0,"cs":"Právě jsem vyhrál","en":"I just won"},{"key":1,"cs":"Jsem připraven závodit","en":"I''m ready to race"},{"key":2,"cs":"Jdu slavit","en":"I''m going to celebrate"},{"key":3,"cs":"Jsem úplně vyčerpaný","en":"I''m completely exhausted"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-sleepy-keyboard-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Cat_Sleeping_on_Keyboard.jpg","answer_index":3},{"id":"meme2-sleepy-keyboard-cat-medium-2","image_key":"q23meme-keyboard-sleep","difficulty":"medium","prompt_cs":"Jaký je vtip u memů s kočkou spící na klávesnici?","prompt_en":"What''s the joke of a cat sleeping on the keyboard?","options":[{"key":0,"cs":"Kočka umí létat","en":"The cat can fly"},{"key":1,"cs":"Má vypadat pracovitě, ale jen odpočívá","en":"It looks like it''s working but is just napping"},{"key":2,"cs":"Kočka vyhrává turnaj","en":"The cat wins a tournament"},{"key":3,"cs":"Kočka má tajný plán","en":"The cat has a secret plan"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-sleepy-keyboard-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Cat_Sleeping_on_Keyboard.jpg","answer_index":1},{"id":"meme2-sleepy-keyboard-cat-hard-2","image_key":"q23meme-keyboard-sleep","difficulty":"hard","prompt_cs":"Na jakém kontrastu stojí mem se spící kočkou?","prompt_en":"What contrast is the sleepy-cat meme built on?","options":[{"key":0,"cs":"Sport proti umění","en":"Sports versus art"},{"key":1,"cs":"Horko versus mráz","en":"Heat versus frost"},{"key":2,"cs":"Dovolená versus výlet","en":"Holiday versus outing"},{"key":3,"cs":"Pracovní povinnosti versus neodolatelná únava","en":"Work duties versus irresistible sleepiness"}],"image_url":"https://foxey-cz.github.io/GuessTheGame-Web/quizoria/media/commons/meme-sleepy-keyboard-cat.jpg","source_url":"https://commons.wikimedia.org/wiki/File:Cat_Sleeping_on_Keyboard.jpg","answer_index":3}]'::jsonb) AS x(
  id text,image_key text,difficulty text,prompt_cs text,prompt_en text,
  options jsonb,answer_index integer,image_url text,source_url text
 )
)
INSERT INTO arcade_private.quizoria_meme_bonus_questions(
 id,image_key,difficulty,prompt_cs,prompt_en,options,answer_index,
 image_url,source_url,author,license)
SELECT i.id,i.image_key,i.difficulty,i.prompt_cs,i.prompt_en,i.options,i.answer_index,
 i.image_url,i.source_url,a.author,a.license_name
FROM input i JOIN arcade_private.foxey_media_assets a ON a.asset_key=i.image_key
WHERE a.status='approved' AND a.commercial_use AND a.redistribution_allowed
 AND i.source_url=a.source_url AND i.image_url=a.asset_url
ON CONFLICT(id) DO NOTHING;
COMMIT;
